export type BlushMode = 'wave' | 'lines' | 'scribble' | 'none'

export type Point = readonly [number, number]

export type FeatureName =
  | 'leftHead'
  | 'rightHead'
  | 'leftBrow'
  | 'rightBrow'
  | 'leftEye'
  | 'rightEye'
  | 'mouth'

type Geometry = Record<FeatureName, readonly Point[]>

export type FeatureBounds = {
  x: number
  y: number
  width: number
  height: number
  cx: number
  cy: number
}

export type RigStyle = {
  headFill: string
  browFill: string
  browStroke: string
  browWarmStroke: string
  browLightStroke: string
  browTextureOpacity: number
  browAccentOpacity: number
  browAccentStrokeWidth: number
  eyeFill: string
  eyeStroke: string
  eyeWarmStroke: string
  eyeLightStroke: string
  eyeHatchOpacity: number
  eyeTextureTilt: number
  eyeTextureLength: number
  upperLidStroke: string
  upperLidOpacity: number
  upperLidStrokeWidth: number
  lowerLidStroke: string
  lowerLidOpacity: number
  lowerLidStrokeWidth: number
  eyeBaselineOpacity: number
  eyeBaselineExtend: number
  eyeBaselineTilt: number
  mouthFill: string
  mouthStroke: string
  cheekFill: string
  cheekStroke: string
  cheekOpacity: number
  cheekFillFactor: number
  cheekRx: number
  cheekRy: number
  blushWaveScale: number
  blushLineFactor: number
  pupilFill: string
  pupilOpacity: number
  pupilRadius: number
  highlightFill: string
  highlightStroke: string
  highlightOpacity: number
  highlightLeftRx: number
  highlightLeftRy: number
  highlightLeftRotate: number
  highlightRightRx: number
  highlightRightRy: number
  highlightRightRotate: number
  tongueFill: string
  tongueOpacity: number
  mouthCapFill: string
  mouthCapOpacity: number
}

export type DetailLayer = {
  index: number
  opacity: number
}

export type RigFrame = {
  points: Record<FeatureName, readonly Point[]>
  paths: Record<FeatureName, string>
  bounds: Record<FeatureName, FeatureBounds>
  style: RigStyle
  pupilLeft: Point
  pupilRight: Point
  highlightLeft: Point
  highlightRight: Point
  cheekLeft: Point
  cheekRight: Point
  blushOpacity: number
  tongue: {
    cx: number
    cy: number
    rx: number
    ry: number
  }
  mouthCap: {
    cx: number
    cy: number
    rx: number
    ry: number
  }
  blushMode: BlushMode
  detailLayers: readonly DetailLayer[]
}

