const blushModes: readonly BlushMode[] = ['wave', 'lines', 'none', 'scribble', 'lines', 'none']

function closedPath(points: readonly Point[]) {
  const firstMidX = (points[0][0] + points[1][0]) / 2
  const firstMidY = (points[0][1] + points[1][1]) / 2
  let path = `M ${firstMidX.toFixed(2)} ${firstMidY.toFixed(2)}`

  for (let index = 1; index < points.length; index += 1) {
    const point = points[index]
    const next = points[(index + 1) % points.length]
    path += ` Q ${point[0].toFixed(2)} ${point[1].toFixed(2)} ${(
      (point[0] + next[0]) /
      2
    ).toFixed(2)} ${((point[1] + next[1]) / 2).toFixed(2)}`
  }

  return `${path} Z`
}

function featureBounds(points: readonly Point[]): FeatureBounds {
  const xs = points.map((point) => point[0])
  const ys = points.map((point) => point[1])
  const x = Math.min(...xs)
  const y = Math.min(...ys)
  const maxX = Math.max(...xs)
  const maxY = Math.max(...ys)

  return {
    x,
    y,
    width: maxX - x,
    height: maxY - y,
    cx: (x + maxX) / 2,
    cy: (y + maxY) / 2,
  }
}

function finalizeFrameGeometry(points: Record<FeatureName, readonly Point[]>) {
  const paths = {} as Record<FeatureName, string>
  const bounds = {} as Record<FeatureName, FeatureBounds>

  ;(Object.keys(points) as FeatureName[]).forEach((feature) => {
    bounds[feature] = featureBounds(points[feature])
    paths[feature] = closedPath(points[feature])
  })

  return { paths, bounds }
}

export function createStaticRigFrame(index: number): RigFrame {
  const safeIndex = Math.max(0, Math.min(geometries.length - 1, index))
  const geometry = geometries[safeIndex]
  const points = {
    leftHead: [...geometry.leftHead],
    rightHead: [...geometry.rightHead],
    leftBrow: [...geometry.leftBrow],
    rightBrow: [...geometry.rightBrow],
    leftEye: [...geometry.leftEye],
    rightEye: [...geometry.rightEye],
    mouth: [...geometry.mouth],
  } satisfies Record<FeatureName, readonly Point[]>
  const { paths, bounds } = finalizeFrameGeometry(points)
  const style = styles[safeIndex]
  const mouthBounds = bounds.mouth

  return {
    points,
    paths,
    bounds,
    style: { ...style },
    pupilLeft: [...pupilPositions[safeIndex].left] as Point,
    pupilRight: [...pupilPositions[safeIndex].right] as Point,
    highlightLeft: [...highlightPositions[safeIndex].left] as Point,
    highlightRight: [...highlightPositions[safeIndex].right] as Point,
    cheekLeft: [...cheekPositions[safeIndex].left] as Point,
    cheekRight: [...cheekPositions[safeIndex].right] as Point,
    blushOpacity: style.cheekOpacity,
    tongue: {
      cx: mouthBounds.cx,
      cy: mouthBounds.y + mouthBounds.height * 0.7,
      rx: mouthBounds.width * 0.22,
      ry: mouthBounds.height * 0.2,
    },
    mouthCap: {
      cx: mouthBounds.cx - 8,
      cy: mouthBounds.y - 8,
      rx: 25,
      ry: 12,
    },
    blushMode: blushModes[safeIndex],
    detailLayers: EXACT_DETAIL_INDICES.has(safeIndex)
      ? [{ index: safeIndex, opacity: 1 }]
      : [],
  }
}
